// StatsDialog.cpp: 瀹炵幇鏂囦欢 //  #include "pch.h" #include "framework.h" #include "MFCApplication2.h" #include "StatsDialog.h" #include "afxdialogex.h"  // CStatsDialog 瀵硅瘽妗? CStatsDialog::CStatsDialog(CWnd* pParent /*=nullptr*/) 	: CDialogEx(IDD_STATS_DIALOG, pParent) 	, m_nTotalChanges(0) { 	m_hIcon = AfxGetApp()->LoadIcon(IDR_MAINFRAME); }  void CStatsDialog::DoDataExchange(CDataExchange* pDX) { 	CDialogEx::DoDataExchange(pDX); }  BEGIN_MESSAGE_MAP(CStatsDialog, CDialogEx) 	ON_WM_SYSCOMMAND() 	ON_WM_PAINT() 	ON_WM_QUERYDRAGICON() 	ON_BN_CLICKED(IDC_CLOSE_STATS_BUTTON, &CStatsDialog::OnBnClickedCloseStats) END_MESSAGE_MAP()  // CStatsDialog 娑堟伅澶勭悊绋嬪簭  BOOL CStatsDialog::OnInitDialog() { 	CDialogEx::OnInitDialog();  	// 灏嗏€滃叧浜?..鈥濊彍鍗曢」娣诲姞鍒扮郴缁熻彍鍗曚腑銆?	// IDM_ABOUTBOX 蹇呴』鍦ㄧ郴缁熷懡浠よ寖鍥村唴銆?	ASSERT((IDM_ABOUTBOX & 0xFFF0) == IDM_ABOUTBOX); 	ASSERT(IDM_ABOUTBOX < 0xF000);  	CMenu* pSysMenu = GetSystemMenu(FALSE); 	if (pSysMenu != nullptr) 	{ 		BOOL bNameValid; 		CString strAboutMenu; 		bNameValid = strAboutMenu.LoadString(IDS_ABOUTBOX); 		ASSERT(bNameValid); 		if (!strAboutMenu.IsEmpty()) 		{ 			pSysMenu->AppendMenu(MF_SEPARATOR); 			pSysMenu->AppendMenu(MF_STRING, IDM_ABOUTBOX, strAboutMenu); 		} 	}  	// 璁剧疆姝ゅ璇濇鐨勫浘鏍囥€?褰撳簲鐢ㄧ▼搴忎富绐楀彛涓嶆槸瀵硅瘽妗嗘椂锛屾鏋跺皢鑷姩 	// 鎵ц姝ゆ搷浣?	SetIcon(m_hIcon, TRUE);         // 璁剧疆澶у浘鏍?	SetIcon(m_hIcon, FALSE);        // 璁剧疆灏忓浘鏍? 	// 鏇存柊鏄剧ず鐨勭粺璁′俊鎭?	CString strText; 	strText.Format(_T("鍥涜竟褰㈡€诲叡鍙樺寲浜?%d 娆?), CShapeDialog::s_nGlobalTotalChanges); 	SetDlgItemText(IDC_STATS_TEXT, strText);  	return TRUE; // 闄ら潪灏嗙劍鐐硅缃埌鎺т欢锛屽惁鍒欒繑鍥?TRUE }  void CStatsDialog::OnSysCommand(UINT nID, LPARAM lParam) { 	if ((nID & 0xFFF0) == IDM_ABOUTBOX) 	{ 		CAboutDlg dlgAbout; 		dlgAbout.DoModal(); 	} 	else 	{ 		CDialogEx::OnSysCommand(nID, lParam); 	} }  // 濡傛灉鍚戝璇濇娣诲姞鏈€灏忓寲鎸夐挳锛屽垯闇€瑕佷笅闈㈢殑浠ｇ爜 // 鏉ョ粯鍒惰鍥炬爣銆?瀵逛簬浣跨敤鏂囨。/瑙嗗浘妯″瀷鐨?MFC 搴旂敤绋嬪簭锛?// 杩欏皢鐢辨鏋惰嚜鍔ㄥ畬鎴愩€? void CStatsDialog::OnPaint() { 	if (IsIconic()) 	{ 		CPaintDC dc(this); // 鐢ㄤ簬缁樺埗鐨勮澶囦笂涓嬫枃  		SendMessage(WM_ICONERASEBKGND, reinterpret_cast<WPARAM>(dc.GetSafeHdc()), 0);  		// 浣垮浘鏍囧湪宸ヤ綔鍖虹煩褰腑灞呬腑 		int cxIcon = GetSystemMetrics(SM_CXICON); 		int cyIcon = GetSystemMetrics(SM_CYICON); 		CRect rect; 		GetClientRect(&rect); 		int x = (rect.Width() - cxIcon + 1) / 2; 		int y = (rect.Height() - cyIcon + 1) / 2;  		// 缁樺埗鍥炬爣 		dc.DrawIcon(x, y, m_hIcon); 	} 	else 	{ 		CDialogEx::OnPaint(); 	} }  // 褰撶敤鎴锋嫋鍔ㄦ渶灏忓寲绐楀彛鏃剁郴缁熻皟鐢ㄦ鍑芥暟鍙栧緱鍏夋爣 // 鏄剧ず銆?HCURSOR CStatsDialog::OnQueryDragIcon() { 	return static_cast<HCURSOR>(m_hIcon); }  void CStatsDialog::OnBnClickedCloseStats() { 	// 鍏抽棴瀵硅瘽妗?	EndDialog(IDCANCEL); }